def remove_Occ(s, c):
    if not s:
        return s

    first_occurrence = -1
    last_occurrence = -1

    for i in range(len(s)):
        if s[i] == c:
            if first_occurrence == -1:
                first_occurrence = i
            last_occurrence = i

    if first_occurrence == -1:
        return s

    new_string = s[:first_occurrence] + s[first_occurrence+1:last_occurrence] + s[last_occurrence+1:]
    return new_string

