def eulerian_num(n, m):
    if m > n:
        return 0
    if n == 0 and m == 0:
        return 1
    if n == 0 or m < 0:
        return 0

    dp = [[0 for _ in range(m + 1)] for _ in range(n + 1)]
    dp[0][0] = 1

    for i in range(1, n + 1):
        for j in range(m + 1):
            dp[i][j] = (i - j) * dp[i - 1][j] + (j + 1) * dp[i - 1][j - 1] if j >= 0 else (i - j) * dp[i - 1][j]

    return dp[n][m]

