        sum_divisors = 1
        for i in range(2, int(n**0.5) + 1):
            if n % i == 0:
                sum_divisors += i
                if i != n // i:
                    sum_divisors += n // i
        return sum_divisors

    amicable_sum = 0
    amicable_pairs = set()

    for a in range(2, limit + 1):
        b = sum_proper_divisors(a)
        if a != b and b <= limit and sum_proper_divisors(b) == a:
            if (a, b) not in amicable_pairs and (b, a) not in amicable_pairs:
