def find_solution(a, b, n):
    if n % gcd(a, b) != 0:
        return None
    x0, y0 = extended_gcd(a, b)
    x = x0 * (n // gcd(a, b))
    y = y0 * (n // gcd(a, b))
    return (x, y)

def gcd(a, b):
    if b == 0:
        return a
    return gcd(b, a % b)

def extended_gcd(a, b):
    if a == 0:
        return (0, 1)
    x1, y1 = extended_gcd(b % a, a)
    x = y1 - (b // a) * x1
    y = x1
    return (x, y)

