def get_total_number_of_sequences(m: int, n: int) -> int:
    dp = {}

    def solve(index, prev):
        if index == n:
            return 1

        if (index, prev) in dp:
            return dp[(index, prev)]

        count = 0
        for i in range(max(1, 2 * prev), m + 1):
            count += solve(index + 1, i)

        dp[(index, prev)] = count
        return count

    return solve(0, 1)

