def max_aggregate(tuples_list):
    """
    Calculate the maximum aggregate from the list of tuples.
    For example:
    max_aggregate([('Juan Whelan',90),('Sabah Colley',88),('Peter Nichols',7),('Juan Whelan',122),('Sabah Colley',84)])==('Juan Whelan', 212)
    """
    name_dict = {}
    for name, value in tuples_list:
        if name in name_dict:
            name_dict[name] += value
        else:
            name_dict[name] = value
    max_name = max(name_dict, key=name_dict.get)
    return (max_name, name_dict[max_name])

