import math

def count_binary_seq(n):
    if n < 0:
        return 0
    if n == 0:
        return 1

    dp = {}

    def solve(index, current_sum):
        if index == n:
            return 1 if current_sum == 0 else 0

        if (index, current_sum) in dp:
            return dp[(index, current_sum)]

        count = solve(index + 1, current_sum + 1) + solve(index + 1, current_sum - 1)
        dp[(index, current_sum)] = count
        return count

    return solve(0, 0)

