def get_max_sum(n):
    if n == 0:
        return 0
    if n == 1:
        return 1

    memo = {}

    def solve(n):
        if n in memo:
            return memo[n]

        if n == 0:
            return 0
        if n == 1:
            return 1

        val1 = 0
        if n // 2 >= 1:
            val1 = solve(n // 2)
        if n // 3 >= 1:
            val1 += solve(n // 3)
        if n // 4 >= 1:
            val1 += solve(n // 4)
        if n // 5 >= 1:
            val1 += solve(n // 5)

        val2 = n

        result = max(val1, val2)
        memo[n] = result
        return result

    return solve(n)

