        max_sum = max(max_sum, n // 4 + get_max_sum(n - n // 4, memo))
    if n >= 5:
        max_sum = max(max_sum, n // 5 + get_max_sum(n - n // 5, memo))

    memo[n] = max_sum
    return max_sum
```

