def max_sub_array_sum(arr, size):
    max_so_far = 0
    current_max = 0
    for i in range(size):
        current_max += arr[i]
        if current_max < 0:
            current_max = 0
        if max_so_far < current_max:
            max_so_far = current_max
    if max_so_far == 0:
        max_so_far = max(arr)
    return max_so_far

