def largest_subset(nums):
    def gcd(a, b):
        if b == 0:
            return a
        return gcd(b, a % b)

    def find_largest_subset(nums, index, current_subset):
        if index == len(nums):
            return len(current_subset)

        max_size = find_largest_subset(nums, index + 1, current_subset)

        is_divisible = True
        for num in current_subset:
            if gcd(num, nums[index]) != 1:
                is_divisible = False
                break

        if is_divisible:
            max_size = max(max_size, find_largest_subset(nums, index + 1, current_subset + [nums[index]]))

        return max_size

    return find_largest_subset(nums, 0, [])

