def get_median(list1, list2, n):
    if n <= 0:
        return None
    if n == 1:
        return (list1[0] + list2[0]) / 2
    if n == 2:
        return (max(list1[0], list2[0]) + min(list1[1], list2[1])) / 2

    m1 = list1[n // 2]
    m2 = list2[n // 2]

    if m1 == m2:
        return m1

    if m1 < m2:
        if n % 2 == 0:
            return get_median(list1[n // 2:], list2[:n // 2], n // 2)
        else:
            return get_median(list1[n // 2:], list2[:n // 2 + 1], n // 2 + 1)
    else:
        if n % 2 == 0:
            return get_median(list1[:n // 2], list2[n // 2:], n // 2)
        else:
            return get_median(list1[:n // 2 + 1], list2[n // 2:], n // 2 + 1)

