def get_coordinates(coordinate):
    x, y = coordinate
    coordinates = []
    for i in range(x - 1, x + 2):
        for j in range(y - 1, y + 2):
            if (i, j) != coordinate:
                coordinates.append([i, j])
    return coordinates

