def maxAverageOfPath(matrix):
    rows, cols = len(matrix), len(matrix[0])
    memo = {}

    def solve(row, col, current_sum, path_length):
        if (row, col, current_sum, path_length) in memo:
            return memo[(row, col, current_sum, path_length)]

        if row == rows - 1 and col == cols - 1:
            return (current_sum + matrix[row][col]) / (path_length + 1)

        if row >= rows or col >= cols:
            return float('-inf')

        down = solve(row + 1, col, current_sum + matrix[row][col], path_length + 1)
        right = solve(row, col + 1, current_sum + matrix[row][col], path_length + 1)

        memo[(row, col, current_sum, path_length)] = max(down, right)
        return memo[(row, col, current_sum, path_length)]

    return solve(0, 0, 0, 0)
```

