def sum_Of_Subarray_Prod(lst):
    n = len(lst)
    total_sum = 0
    for i in range(1 << n):
        sublist = []
        for j in range(n):
            if (i >> j) & 1:
                sublist.append(lst[j])
        if sublist:
            product = 1
            for num in sublist:
                product *= num
            total_sum += product
    return total_sum

