def is_polite(n):
    if n <= 0:
        return 0
    if n == 1:
        return 1

    low = 1
    high = 2 * n

    while low <= high:
        mid = (low + high) // 2
        count = 0
        for i in range(1, mid + 1):
            if mid % i == 0:
                count += 1

        if count >= n:
            high = mid - 1
        else:
            low = mid + 1

    return low

