    opening_brackets = ['(', '[', '{']
    closing_brackets = [')', ']', '}']
    bracket_map = {')': '(', ']': '[', '}': '{'}

    for char in expression:
        if char in opening_brackets:
            stack.append(char)
        elif char in closing_brackets:
            if not stack:
                return False
            top_element = stack.pop()
            if bracket_map[char] != top_element:
                return False

    return not stack

